<?php use App\Services\{ContentImageService as Images,ManagementService as M};use App\Core\Database as DB; ?>
<div class="catalogue-grid"><?php foreach($rows as $r): $title=$r['display_title']??$r['name']??$r['code']??('#'.$r['id']); ?>
<article class="card catalogue-card"><?= Images::thumbnail($r['cover_asset_id']??null,$title) ?><div class="catalogue-body"><span class="pill"><?= e(tr($r['status']??($r['is_active']?'Active':'inactive'))) ?></span><h2><?= e($title) ?></h2>
<?php if($section==='subjects'): $associated=DB::all('SELECT c.name FROM courses c JOIN course_subjects cs ON cs.course_id=c.id WHERE cs.subject_id=? AND cs.is_active=1 ORDER BY c.name',[$r['id']]); ?><p class="muted"><?= e(implode(' · ',array_column($associated,'name'))) ?></p><?php else: ?><p class="muted"><?= e(DB::val('SELECT name FROM subjects WHERE id=?',[$r['subject_id']])??'') ?><?php if($section==='lessons'): ?> · <?= e(tr($r['item_type'])) ?><?php endif; ?></p><?php endif; ?>
<div class="catalogue-links"><?php if(M::canWrite($section,isset($r['subject_id'])?(int)$r['subject_id']:null)): ?><a class="btn" href="<?= e($link(['edit'=>$r['id']])) ?>"><?= e(tr('Edit')) ?></a><?php endif; ?><?php if($section==='subjects'): ?><a class="btn" href="modules.php?subject_id=<?= (int)$r['id'] ?>"><?= e(tr('Modules')) ?></a><?php elseif($section==='modules'): ?><a class="btn" href="lessons.php?subject_id=<?= (int)$r['subject_id'] ?>"><?= e(tr('Lessons')) ?></a><?php else: ?><a class="btn" href="lesson.php?id=<?= (int)$r['id'] ?>"><?= e(tr('Preview')) ?></a><?php endif; ?></div></div></article><?php endforeach; ?></div>
<?php if(!$rows): ?><section class="card empty-state"><?= e(tr('No results found.')) ?></section><?php endif; ?>
